// T80: loaders for the landing page's "The result" section. Everything shown comes from the published report files:
// self/forward.json (the pre-registered forward test), self/review-1/decisions.json (v1) and
// self/review-1b/decision.json (the same tasks under the v2 gate). Each loader is pure over parsed JSON.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

export interface ForwardResult {
  wording: string;
  n: number;
  newOnly: number;
  oldOnly: number;
  both: number;
  neither: number;
  p: number;
}

/** One gate call: the verdict string and the reasons exactly as the file gives them. */
export interface GateCall {
  verdict: string;
  reasons: string[];
  hiddenPass?: { incumbent: number; candidate: number };
}

export interface Result {
  forward: ForwardResult | null;
  v1: GateCall | null;
  v2: GateCall | null;
}

const DATA = join(process.cwd(), "public", "data");

const object = (v: unknown): Record<string, unknown> | null =>
  typeof v === "object" && v !== null && !Array.isArray(v) ? (v as Record<string, unknown>) : null;
const num = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const strings = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : []);

function forward(json: unknown): ForwardResult | null {
  const s = object(object(json)?.summary);
  if (!s || typeof s.wording !== "string") return null;
  const { n, newOnly, oldOnly, both, neither, p } = s;
  if (!num(n) || !num(newOnly) || !num(oldOnly) || !num(both) || !num(neither) || !num(p)) return null;
  return { wording: s.wording, n, newOnly, oldOnly, both, neither, p };
}

function v1(json: unknown): GateCall | null {
  const root = object(json);
  const d = object(Array.isArray(root?.decisions) ? root.decisions[0] : null);
  if (!d || typeof d.verdict !== "string") return null;
  return { verdict: d.verdict, reasons: strings(d.reasons) };
}

function v2(json: unknown): GateCall | null {
  const d = object(json);
  if (!d || typeof d.verdict !== "string") return null;
  const out: GateCall = { verdict: d.verdict, reasons: strings(d.reasons) };
  const h = object(d.hidden_pass);
  if (h && num(h.incumbent) && num(h.candidate)) out.hiddenPass = { incumbent: h.incumbent, candidate: h.candidate };
  return out;
}

/** Builds the section's data from the three parsed files. Any missing or malformed file gives null for its part. */
export function loadResult(forwardJson: unknown, review1Json: unknown, review1bJson: unknown): Result {
  return { forward: forward(forwardJson), v1: v1(review1Json), v2: v2(review1bJson) };
}

function readJson(file: string): unknown {
  if (!existsSync(file)) return undefined;
  try {
    return JSON.parse(readFileSync(file, "utf8"));
  } catch {
    return undefined;
  }
}

/** The section's data from the files under dataDir (default public/data). */
export function loadResultFile(dataDir: string = DATA): Result {
  const self = join(dataDir, "self");
  return loadResult(
    readJson(join(self, "forward.json")),
    readJson(join(self, "review-1", "decisions.json")),
    readJson(join(self, "review-1b", "decision.json")),
  );
}

import { join } from "node:path";
import type { Metadata } from "next";
import { GITHUB } from "@/components/LandingData";
import { loadForwardFile, loadPreregFile, type Forward, type ForwardRow } from "@/lib/forward";

export const metadata: Metadata = {
  title: "Experiment · Roster",
  description:
    "The pre-registered forward run: the frozen backlog, and every paired task as it lands.",
};

const DATA = join(process.cwd(), "public", "data");
const PREREG_URL = `${GITHUB}/blob/main/experiments/PREREGISTRATION.md`;

const pass = (v: boolean) => (v ? "pass" : "fail");
const usd = (v: number | null) => (v === null ? <span className="na">n/a</span> : `$${v.toFixed(2)}`);

function Pairs({ rows, summary }: { rows: ForwardRow[]; summary: Forward["summary"] }) {
  return (
    <section style={{ marginTop: 32 }}>
      <h2 style={{ fontSize: "1.15rem", margin: "0 0 12px" }}>Pairs</h2>
      {summary && (
        <div className="banner" style={{ color: "var(--fg)" }}>
          {summary.wording}
          <span className="sub">
            {summary.n} paired tasks · {rows.length} shown
            {summary.skipped > 0
              ? ` · ${summary.skipped} malformed row${summary.skipped === 1 ? "" : "s"} skipped`
              : ""}
          </span>
        </div>
      )}
      {rows.length === 0 ? (
        <div className="empty">No pairs have been graded yet.</div>
      ) : (
        <div className="scroll">
          <table>
            <thead>
              <tr>
                <th>Task</th>
                <th>Old setup</th>
                <th>New setup</th>
                <th>Old cost</th>
                <th>New cost</th>
                <th>Excluded</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r, i) => (
                <tr key={`${r.task}-${i}`}>
                  <td>{r.task}</td>
                  <td>{pass(r.old)}</td>
                  <td>{pass(r.new)}</td>
                  <td className="num">{usd(r.costOld)}</td>
                  <td className="num">{usd(r.costNew)}</td>
                  <td>{r.excluded === undefined ? "none" : r.excluded}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

export default function ExperimentPage() {
  const forward = loadForwardFile(DATA);
  const sha256 = loadPreregFile(DATA);

  return (
    <>
      <h1>The experiment</h1>
      <p className="lede">
        Roster built itself with several agent setups, reviewed its own sessions, and promoted one setup. Before
        that review ran, we froze a backlog of new tasks and their acceptance tests. This page reports the forward
        run: every frozen task, run through both the demoted and the promoted setup, graded blind. The
        hypotheses, tests and stop rules are fixed in{" "}
        <a href={PREREG_URL} rel="noopener noreferrer">PREREGISTRATION.md</a>.
      </p>
      {sha256 && (
        <p className="meta">Frozen backlog sha256: {sha256}</p>
      )}
      {forward === null ? (
        <div className="empty">The forward run has not started</div>
      ) : (
        <Pairs rows={forward.rows} summary={forward.summary} />
      )}
    </>
  );
}

